SELECT Go.IdP, Scuola.AnnoS, [Go.Cognome] & " " & [Go.Nome] AS NominativoU, [Comuni_2.Comune] & " " & [Comuni_2.Slov] AS ComN, Comuni_2.Slov, Go.DataN, Go.Via, [Go.Via] & " " & [Comuni_3.Slov] & " " & [Comuni_3.Cap] AS ComR, Comuni_3.Slov, Go.tel, Go.mail, Go.cel, Go.[davcna koda], [Starsi.Cognome] & " " & [Starsi.Nome] AS NominativoS, Starsi.Cognome, Starsi.Nome, Starsi.DataN, Comuni.Comune, Comuni.Slov, Starsi.Via, Comuni_1.Comune, Comuni_1.Slov, Starsi.davcna, Materia.Materia, Prof.Cognome, Prof.Nome, Podruzica.Dove, Scuola.Razred, Sola!Sola & " " & Sola!Razred AS Scuola
FROM (((Materia RIGHT JOIN ((((((([Go] LEFT JOIN LSP ON Go.IdP=LSP.IdP) LEFT JOIN Starsi ON LSP.IdS=Starsi.IdS) LEFT JOIN Comuni ON Starsi.IdLN=Comuni.IdC) LEFT JOIN Comuni AS Comuni_1 ON Starsi.IdLR=Comuni_1.IdC) LEFT JOIN Comuni AS Comuni_2 ON Go.IdCN=Comuni_2.IdC) LEFT JOIN Comuni AS Comuni_3 ON Go.IdCR=Comuni_3.IdC) LEFT JOIN Scuola ON Go.IdP=Scuola.IdP) ON Materia.IdM=Scuola.IdM) LEFT JOIN Prof ON Scuola.IdPr=Prof.IdPr) LEFT JOIN Podruzica ON Scuola.IdD=Podruzica.IdD) LEFT JOIN Sola ON (Scuola.AnnoS=Sola.AnnoS) AND (Scuola.IdP=Sola.IdP)
WHERE (((Scuola.AnnoS) Like [Solsko leto?]))
ORDER BY [Go.Cognome] & " " & [Go.Nome];
